parameters.jsCode:
const telegram = $('Prepare Telegram Input').first().json;

const userId = String(telegram.userId ?? telegram.user_id);
const chatId = String(telegram.chatId ?? telegram.chat_id);

const reply = String(
  telegram.chatInput ?? telegram.chat_input ?? ''
).trim().toUpperCase();

const active = $input.all()
  .map(item => item.json)
  .filter(row =>
    String(row.user_id) === userId &&
    String(row.chat_id) === chatId &&
    row.status === 'pending' &&
    [0, 1].includes(Number(row.confirmation_count))
  );

if (active.length !== 1) {
  return [{
    json: {
      valid: false,
      reply,
      message: active.length === 0
        ? 'No active email deletion request was found.'
        : 'Multiple active deletion requests were found. Please cancel the existing requests and start again.'
    }
  }];
}

return [{
  json: {
    valid: true,
    reply,
    ...active[0],
    confirmation_count: Number(active[0].confirmation_count)
  }
}];

